class ScriptProductionMetadataGenerator { public function generateForScript(Script $script, ?BulletinPromptRun $run=null): array { $run ??= $script->bulletinPromptRun; $run?->loadMissing(['bulletinType.location','bulletinType.newsCategory','edition']); $parsed = is_array($run?->parsed_response) ? $run->parsed_response : ((is_array($script->metadata) && is_array($script->metadata['parsed_response'] ?? null)) ? $script->metadata['parsed_response'] : []); $finalTitle = trim((string)($parsed['title'] ?? '')) ?: ($script->final_title ?: $script->title); $bt=$run?->bulletinType; $productionName=collect([$bt?->name,$bt?->location?->name,$bt?->newsCategory?->name,$run?->edition?->edition_type,$run?->scheduled_for?->format('Y-m-d H:i')])->filter()->implode(' · '); $intro=trim((string)$script->intro); $items=is_array($parsed['items']??null)?$parsed['items']:[]; $sum=collect($items)->map(fn($i)=>trim((string)($i['summary']??$i['headline']??'')))->filter()->take(4)->implode(' '); $public=Str::limit(trim($intro.' '.$sum),320,'...'); $short=Str::limit($public,160,'...'); $tags=['Noticias','Noticiario','Actualidad',$bt?->location?->name,$bt?->newsCategory?->name,$bt?->name,$run?->edition?->edition_type]; $norm=collect($tags)->filter()->map(fn($t)=>'#'.Str::of($t)->ascii()->replaceMatches('/[^A-Za-z0-9_]/','')->toString())->filter(fn($t)=>$t!=='#')->unique()->take(12)->values()->all(); $platforms=is_array($bt?->target_platforms)&&count($bt->target_platforms)?$bt->target_platforms:['youtube_shorts','tiktok','instagram_reels']; return ['production_name'=>$productionName?:$script->title,'final_title'=>$finalTitle,'public_description'=>$public,'short_description'=>$short,'hashtags'=>$norm,'social_copy'=>trim($finalTitle.' — '.$short.' '.implode(' ', $norm)),'target_platforms'=>$platforms,'seo_title'=>$finalTitle?:$productionName,'seo_description'=>$short,'production_status'=>(($finalTitle&&$productionName&&$public&&count($norm)&&count($platforms))?'draft':'metadata_pending')]; }}
